/* OM DNA — Mediterranean white, ciel blue air, the gold star */
.theme-marseille {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.981 0.008 228.9);
  --surface-2: oklch(0.960 0.016 233.0);
  --fg: oklch(0.284 0.034 250.8);
  --fg-muted: oklch(0.638 0.035 246.9);
  --accent: oklch(0.706 0.128 229.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.767 0.139 91.1);
  --line: oklch(0.932 0.026 231.6);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.706 0.128 229.9);
  --radius: 0.75rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Teko", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-marseille h1,
.theme-marseille h2,
.theme-marseille h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-marseille { --font-ui: var(--font-display); }
.theme-marseille h1, .theme-marseille h2 { text-transform: uppercase; }
.theme-marseille button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-marseille h2::before { content: "★ "; color: var(--accent-2); }
.theme-marseille h1 { font-weight: 600; }
.theme-marseille button { font-weight: 600; }

/* depth */
.theme-marseille thead th { color: oklch(0.45 0.10 240); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid var(--accent); }
.theme-marseille td { border-bottom: 1px solid var(--line); }
.theme-marseille tbody tr:hover { background: oklch(0.706 0.128 229.9 / 9%); }
.theme-marseille a { color: oklch(0.50 0.11 235); text-underline-offset: 3px; }
/* the Mediterranean: links ripple on hover */
.theme-marseille a:hover { text-decoration-style: wavy; text-decoration-color: var(--accent); }
.theme-marseille ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-marseille input:focus-visible, .theme-marseille select:focus-visible, .theme-marseille textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-marseille kbd { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-pill); padding: 0.1em 0.55em; font-family: var(--font-mono); color: oklch(0.45 0.10 240); }
.theme-marseille ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-marseille ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-marseille ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-marseille ::-webkit-scrollbar-thumb:hover { background: oklch(0.60 0.13 235); }
.theme-marseille .label-caps { color: oklch(0.55 0.12 235); }
.theme-marseille .themed-border { border-color: var(--accent); border-bottom-width: 3px; }
.theme-marseille button:hover { box-shadow: 0 4px 14px oklch(0.706 0.128 229.9 / 35%); }

/* alt mode: auto-derived dark variant */
.theme-marseille.alt-mode {
  /* Vélodrome night match — deep sea navy, ciel floodlit */
  --bg: oklch(0.175 0.032 245.0);
  --surface: oklch(0.215 0.038 245.0);
  --surface-2: oklch(0.258 0.045 245.0);
  --fg: oklch(0.97 0.008 230);
  --fg-muted: oklch(0.72 0.035 235);
  --line: oklch(0.706 0.128 229.9 / 22%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-marseille.alt-mode thead th { color: var(--accent); }
.theme-marseille.alt-mode a { color: oklch(0.78 0.11 230); }
.theme-marseille.alt-mode kbd { color: oklch(0.78 0.11 230); }
.theme-marseille.alt-mode .label-caps { color: oklch(0.767 0.139 91.1); }
.theme-marseille.alt-mode tbody tr:hover { background: oklch(0.706 0.128 229.9 / 14%); }
.theme-marseille.alt-mode ::-webkit-scrollbar-thumb:hover { background: oklch(0.78 0.11 230); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
